    "content": "文｜李蛋 七月的横店，明清宫苑景区门口，两拨人擦肩而过。 一拨是刚收工的群演，顶着大太阳走了一整天位，片酬还没结；另一拨是刚换好戏服的中老年阿姨，正兴冲冲往片场赶，手里攥着手机，准备拍一部属于自己的短剧。 摄影棚空置率逼近80%，曾经单日四五十个剧组同时开机的盛况，彻底成了过去时。但“入戏横店”的体验棚里，导演用手机给游客拍戏，两个半小时出一部成片，高峰期一天上百人排队。 街巷转角再也偶遇不到剧组了，但转角遇到“皇太后”的概率，正在直线上升。一位60多岁的上海退休阿姨在家族群里发了自己的成片，儿女们“惊呆了”。她说…"
