    "content": "如果穿越回战国初年，拉住一个路人问“未来靠什么打赢仗”，多半会收获一堆关于兵器的答案：铁剑比青铜更锋利，弩机射得更远，甲胄越造越硬。这些回答都没错，却都不够——因为最后横扫六合的秦国，靠的并不是哪家兵器铺。 铁器把“武装一个士兵”变得便宜。青铜昂贵的年代，打仗是贵族的专利，几百乘战车对冲一下午，胜负就算分出来了；铁一便宜，战争的组织逻辑整个翻了过来——谁能把最多的平民编成军队，谁就赢。秦国把这道题做到了满分：编户齐民、什伍连坐、军功授爵，一整套围绕“人人皆可为兵”重构的制度。兵器铺解决的是“有没有剑”，秦制解决的是…"
