    "description": "新华社纽约8月3日电（记者刘亚南）美国国际贸易法院一份法庭文件显示，美国25个由民主党主政的州3日在该法院进行联合起诉，要求法庭裁定特朗普政府日前以所谓“强迫劳动”为由对60个经济体征收的301关税措施违法、予以废止；在司法审查期间，裁定暂停执行该关税措施。",
