    "content": "新华社洛杉矶8月3日电（记者谭晶晶 高山）美国疾病控制和预防中心3日证实，密歇根州报告两例环孢子虫病相关死亡病例，两名死者均患有严重基础疾病。这是自今年5月环孢子虫病在美持续蔓延以来首次报告相关死亡病例。 美国密歇根州卫生与公共服务部当天公布的最新数据显示，截至目前，密歇根州累计报告环孢子虫病病例11234例，其中193人住院治疗、两人死亡。 该机构表示，医疗记录显示，环孢子虫病感染及脱水可能影响两名死者本身患有的基础疾病。 近期，美国环孢子虫病病例持续增加。美疾控中心、美食品和药物管理局及多个州的公共卫生部门正在…"
