    "content": "新华社华盛顿8月3日消息，针对伊朗否认美伊谈判重启的说法，美国总统特朗普3日在社交媒体发文予以驳斥，坚称谈判已经重启，并威胁伊朗“要么达成协议，要么彻底投降”。 特朗普指责伊朗领导层“极其虚伪”，声称伊方“恳求”进行会谈，谈判已启动，后续会谈也已提上日程，但“他们却公开且傲慢地声称未进行任何讨论，什么事都没谈，他们只是在与‘阿曼’打交道”。 特朗普还称霍尔木兹海峡“已完全由美国海军控制”，“除非达成协议或伊朗彻底投降”，否则美国将继续封锁伊朗港口。他还再次强调，“伊朗绝不可能拥有核武器”。 据伊朗伊斯兰共和国通讯社…"
