    "content": "新华社哈尔滨8月3日电（记者黄腾、董宝森）8月3日傍晚到夜间，黑龙江省连续发布预警信息，气象和水利部门提醒相关地区和单位，密切关注天气形势及雨水情变化、加强分析研判、加强巡查排险等。 黑龙江省水利厅和黑龙江省气象局20时联合发布中小河流洪水气象风险蓝色预警，预计8月3日20时至8月4日20时，大庆市区、杜尔伯特、泰来、齐齐哈尔市区、龙江、肇源、肇州、安达、肇东有一定风险发生中小河流洪水。 黑龙江省气象台21时20分发布强对流预警，预计未来6小时，肇源、肇州、肇东、哈尔滨市区、巴彦、宾县、木兰有短时强降水、雷暴大风等…"
