    "pub_date": "2026-08-03 22:18:44",
    "author": "",
    "description": "“有迤逦碧水入眼，有奇峰峡谷相伴，坐在崖边喝一杯咖啡，便是盛夏独有的治愈享受。”沉醉在贵州省黔西市化屋村“花都里”度假营地的景致中，游客罗女士不禁感叹。",
    "content": "“有迤逦碧水入眼，有奇峰峡谷相伴，坐在崖边喝一杯咖啡，便是盛夏独有的治愈享受。”沉醉在贵州省黔西市化屋村“花都里”度假营地的景致中，游客罗女士不禁感叹。"
