    "content": "新华社北京8月3日电 消息人士披露，对伊朗的战事陷入僵局之时，美军中央司令部开始在内部广泛征集“有创意、非常规”的建议以打开局面。 美国有线电视新闻网（CNN）3日援引两名消息人士的话报道，中央司令部一名高级军官上周在发给众多军方分析师的电子邮件中写道：“我们正在寻求有创意、非常规方式，以施压和惩罚伊朗”。 一些美军官员表示，在美军中发送电子邮件广泛征求建议的方式并不常见。CNN说，这反映了美国政府在迫使伊朗同意达成协议方面的选项已经所剩不多。 美国总统特朗普7月底威胁称，他正“认真考虑”恢复对伊朗的大规模作战行动…"
