    "content": "新华社莫斯科8月3日电（记者黄河）据俄罗斯媒体3日报道，4名扎波罗热核电站的工作人员被地雷炸伤，其中2人伤势较重。 今日俄罗斯通讯社援引扎波罗热核电站新闻处消息报道说，乌克兰武装部队3日凌晨使用无人机在通往核电站所在的埃涅尔戈达尔市的公路上、以及该市工业区所在区域投放地雷，造成4名核电站工作人员在上班途中被地雷炸伤。 俄罗斯国家原子能公司首席执行官利哈乔夫2日表示，自4月27日以来，乌克兰武装部队对埃涅尔戈达尔市的袭击已经造成15人死亡、51人受伤。 扎波罗热核电站是欧洲最大核电站之一。2022年2月乌克兰危机全面…"
