    "content": "新华社马德里8月3日电（记者孟鼎博 刁泽 李超）近日，约5万名非法移民从摩洛哥方向进入西班牙位于北非的飞地休达，引发近年来西班牙乃至欧洲最严重的边境移民危机。据西班牙方面最新统计，危机已造成至少72人死亡。 危机发生后，欧盟成员国围绕移民问题再度出现政策分歧。专家指出，长期以来，欧盟始终难以解决移民问题，各国在边境管控、责任分担等方面的矛盾日益加剧，移民问题在各国也越发政治化，导致欧盟难以形成有效的移民政策。在此背景下，类似的边境危机未来“或反复上演”。 2026年7月30日，非法移民进入西班牙北非飞地休达。新华社…"
