    "category": "新闻",
    "title": "韩国陆军第一军团指挥官被停职",
    "link": "http://www.news.cn/20260803/7ebe159d58dd497088b223430f88d453/c.html",
    "pub_date": "2026-08-03 21:58:26",
    "author": "王一帆",
    "description": "新华社北京8月3日电 韩国国防部3日宣布，韩国陆军第一军团军团长韩基成（音译）因擅自下令韩军前沿部队执行警戒任务时枪械不装填实弹、以及韩军日前险些误击美军无人机事件，即日起暂时停职。 据韩联社报道，韩基成被指自行下令调整第一军团警戒勤务规范，要求士兵在前沿哨所和一般前哨执行警戒任务时，K6重机枪和K4自动榴弹发射器不装填实弹，而是将弹药置于武器旁。但根据相关规定，前沿部队执勤时必须装填实弹。这一命令引发对前沿部队战备状态松懈、警戒态势不…",
    "content": "新华社北京8月3日电 韩国国防部3日宣布，韩国陆军第一军团军团长韩基成（音译）因擅自下令韩军前沿部队执行警戒任务时枪械不装填实弹、以及韩军日前险些误击美军无人机事件，即日起暂时停职。 据韩联社报道，韩基成被指自行下令调整第一军团警戒勤务规范，要求士兵在前沿哨所和一般前哨执行警戒任务时，K6重机枪和K4自动榴弹发射器不装填实弹，而是将弹药置于武器旁。但根据相关规定，前沿部队执勤时必须装填实弹。这一命令引发对前沿部队战备状态松懈、警戒态势不足的担忧。 韩国陆军地面作战司令部已对所辖全部军团进行检查，以明确是否还有其他部…"
