    "content": "新华社北京8月3日电 希腊消防部门2日说，该国首都雅典所在阿提卡大区的野火明显由一条故障输电线所产生的火花引发。 这是7月29日在希腊克里特岛雷西姆诺地区拍摄的野火。新华社发（拉帕尼斯·斯皮罗斯摄） 发生故障的输电线从一座私营风力发电设施向主电网输电。警方已逮捕2名嫌疑人，分别是负责设计和监督该电力项目的工程师和参与建设输电网络的承包商，他们面临纵火重罪指控。当局还对该风力发电企业的负责人发出了逮捕令。 阿提卡大区野火始于7月31日，借助强风迅速蔓延。迄今这场火灾已迫使超过1000人疏散。 7月29日，在希腊克里特…"
