    "author": "李美娟",
    "description": "在景德镇，十个人中就有一个从事陶瓷相关行业。来自全国乃至世界各地的陶瓷爱好者汇聚于此。为什么越来越多人热爱陶瓷、关注陶瓷？ 在景德镇土生土长的程林曜，是景德镇市级非物质文化遗产代表性项目“景德镇传统青花瓷制作技艺——青花花鸟”代表性传承人。透过她的国际化“朋友圈”，感受一朵青花如何承载东方美学，走向世界，又如何在今天的世界里，绽放出新的美丽纹样。 记者：郑清斌、洪靓、魏寅、李美娟、彭菁 新华社音视频部制作",
    "content": "在景德镇，十个人中就有一个从事陶瓷相关行业。来自全国乃至世界各地的陶瓷爱好者汇聚于此。为什么越来越多人热爱陶瓷、关注陶瓷？ 在景德镇土生土长的程林曜，是景德镇市级非物质文化遗产代表性项目“景德镇传统青花瓷制作技艺——青花花鸟”代表性传承人。透过她的国际化“朋友圈”，感受一朵青花如何承载东方美学，走向世界，又如何在今天的世界里，绽放出新的美丽纹样。 记者：郑清斌、洪靓、魏寅、李美娟、彭菁 新华社音视频部制作"
