    "content": "新华社澳门8月3日电（记者宋晨、齐菲）3日下午，2026澳门国际现代音乐艺术节举行开幕音乐会。活动中，来自中国内地和港澳以及欧美地区的音乐名家，以融合创新的现代音乐作品展现澳门中西文化交融特质，为粤港澳大湾区观众献上高水平国际音乐盛会。 澳门文化界联合总会理事长李自松致辞介绍澳门文化优势，期许艺术节搭建国际交流桥梁、助力湾区文化发展。澳门爵士乐国际交流协会会长聂鑫介绍本届艺术节主题、赛事、论坛、演出及琴澳联动安排，展望打造国际知名音乐文化品牌。 现场还举行了合作签约仪式，澳门爵士乐国际交流协会与有关机构将围绕原创音…"
