    "title": "探秘AI新势力丨脑机接口如何重新连接一个人的生活",
    "link": "http://www.news.cn/20260803/05aeee56804541f6b050d42458f17d7a/c.html",
    "pub_date": "2026-08-03 21:33:17",
    "author": "孙青,李海伟",
    "description": "他们都曾因为意外导致高位截瘫，身体无法行动。身体的桎梏也让他们逐渐远离原本的工作和生活。而现在，他们正在尝试用自己的大脑重新完成这些操作。脑机接口如何重新连接一个人的生活？记者近期探访了正在接受临床试验的三位高位截瘫受试者，他们正在通过脑控实现电商物流协调、自动售卖机后台标注等工作。 目前，阶梯医疗正在开展的临床试验已有23例。依托脑机接口系统，他们已经可以连续工作数小时。借助脑机接口，他们不仅能够控制电脑，也开始尝试控制机械臂、轮椅等…",
    "content": "他们都曾因为意外导致高位截瘫，身体无法行动。身体的桎梏也让他们逐渐远离原本的工作和生活。 而现在，他们正在尝试用自己的大脑重新完成这些操作。脑机接口如何重新连接一个人的生活？记者近期探访了正在接受临床试验的三位高位截瘫受试者，他们正在通过脑控实现电商物流协调、自动售卖机后台标注等工作。 目前，阶梯医疗正在开展的临床试验已有23例。依托脑机接口系统，他们已经可以连续工作数小时。借助脑机接口，他们不仅能够控制电脑，也开始尝试控制机械臂、轮椅等外部设备。 脑机接口最先改变的，也许不是未来世界的某一天，而是今天这些正在努力…"
