    "content": "新华社巴库8月3日电（记者周良）埃里温消息：来自亚美尼亚执政党公民合约党的议员鲁本·鲁比尼扬在3日举行的投票中当选亚美尼亚国民会议（议会）新一任议长。 亚美尼亚议会议员当天就是否同意鲁比尼扬成为新一任议长举行投票。105名议员中有91人参加投票，鲁比尼扬以63票赞成、28票反对的结果当选议长。 亚美尼亚新一届议会2日举行首次会议，公民合约党在会上提名鲁比尼扬为新任议长人选，议会中的两个反对派政党联盟未提名议长人选，鲁比尼扬因此成为议长的唯一候选人。 6月7日，亚美尼亚举行议会选举，公民合约党获得议会105个席位中的…"
