    "content": "新华社哈尔滨8月3日电 题：黑龙江部分受灾地区加速恢复 新华社记者黄腾、董宝森 “水涨得厉害，我当时腿肚子都转筋了。”在黑龙江省尚志市庆阳镇庆阳村，64岁的村民王立君回忆起大水来时的场景仍心有余悸。 7月31日8时至17时，庆阳镇遭遇短时强降雨天气，累计降雨量达157.8毫米，强降雨引发山洪内涝。当晚，王立君全家紧急撤离。他们起初住在镇里学校的临时安置点，随后到亲属家借住。8月3日，看着家里主房并未受影响，他便搬了回来。“现在屋里还有些异味，村里正在加紧清淤、消杀。” 8月1日，针对吉林、黑龙江等地近期暴雨洪涝灾害…"
