    "content": "近日，上海市民政局发布《上海市民政事业发展“十五五”规划》（以下简称《规划》），提出到2030年，全面建成与上海社会主义现代化国际大都市相适应的民政事业发展格局，让人民群众享有更高质量的民政服务，推动全体人民共同富裕迈出坚实步伐，人民群众的获得感、幸福感、安全感进一步提高。 《规划》共设置了11项主要指标，涵盖养老服务、社会救助、社会福利、社会事务和社会治理等领域。其中，前3项为约束性指标，包括：养老机构护理型床位占比由69%提至75%以上；养老护理员中级及以上技能等级持证率由28%提至35%以上；老年认知障碍照护…"
