    "description": "直播间里，一名女子声称婆婆病重无钱医治，想卖掉传家宝换救命钱，主播说可以高价回收……这一场景，其实是诈骗团伙根据剧本进行的表演。 近期，山东省高青县警方成功打掉一个以“高价回收老物件”为幌子的电信网络诈骗团伙，涉案金额200余万元，270多名中老年人落入精心布设的陷阱。 骗子是如何设局的？如何防范此类诈骗？ 这是警方查获的诈骗团伙直播所用道具。（受访对象供图） “高价回收”只是噱头 泛黄的粮票估价数万元，生锈的自行车号称能卖两三万元………",
