    "author": "申铖",
    "description": "新华社北京8月3日电 记者8月3日从财政部了解到，财政部近日会同农业农村部、水利部下达农业防灾减灾和水利救灾资金21.54亿元。 据介绍，三部门此次下达资金，一是支持广西、湖北、湖南、广东、重庆、贵州等6省（自治区、直辖市）开展水利工程设施水毁修复等洪涝、地震灾后救灾工作，助力保障水利工程安全运行；二是支持辽宁、吉林、浙江、广西、湖北等5省（自治区）开展在田作物肥水管理、绝收地块改种补种、畜牧渔业补栏补苗、损毁设施修复等灾后生产恢复工作…",
