    "content": "新华社杭州8月3日电（记者郑可意）江南夏意长，荷花正可人。清晨五点半，位于杭州市上城区的大马弄已被荷香唤醒。这条不过200多米长的老巷子，眼下成了人们口中的“荷花街”。天还没亮透，就有市民从萧山、城西赶来，甚至有爱花人从海宁、绍兴跨城而至，高峰时甘愿排队一个多小时，只为带一份属于杭州的夏日浪漫回家。 上午七点左右，只见巷子里重瓣荷花、带露荷叶热热闹闹地排开，卖花人动作娴熟，手上一刻不停。最早在巷子里卖荷花的商户夏女士身着一袭旗袍，将新鲜的荷花搭配上向日葵、莲蓬、竹叶，再裹上印有《爱莲说》的包装纸，为顾客递上一束束江…"
