    "author": "张申博,姜辰蓉",
    "description": "北出陕西榆林定边县城十里，就到了十里沙，这里是毛乌素沙地的南缘。 十里沙不见沙。放眼望去，樟子松林密密匝匝地铺向天际。盛夏毒辣辣的日头下，这片墨绿透出一种近乎固执的沉稳。 无人机嗡嗡巡弋，整片林海翻涌在屏幕上；林间空地上整齐排列着现代化造林设备，随时可以投入管护作业。 29岁的石健阳站在树下，抬手抚过粗糙的松皮。皲裂的树皮让他想起祖父石光银那双手，那双大半辈子都为种树而操劳的手。 20世纪80年代，那双手变卖了家中84只羊，签下承包合同…",
    "content": "北出陕西榆林定边县城十里，就到了十里沙，这里是毛乌素沙地的南缘。 十里沙不见沙。放眼望去，樟子松林密密匝匝地铺向天际。盛夏毒辣辣的日头下，这片墨绿透出一种近乎固执的沉稳。 无人机嗡嗡巡弋，整片林海翻涌在屏幕上；林间空地上整齐排列着现代化造林设备，随时可以投入管护作业。 29岁的石健阳站在树下，抬手抚过粗糙的松皮。皲裂的树皮让他想起祖父石光银那双手，那双大半辈子都为种树而操劳的手。 20世纪80年代，那双手变卖了家中84只羊，签下承包合同，带着300多位乡亲扎进狼窝沙。四十多年里，那双手刨过滚烫的沙坑，扶起被风刮倒的…"
