    "content": "新华社香港8月3日电（记者郑静霞）据香港证券及期货事务监察委员会（香港证监会）3日消息，该委员会与中国证券监督管理委员会（中国证监会）联合公布一系列措施，以深化务实合作和协同发展，巩固提升香港国际金融中心地位。 据了解，新措施涵盖上市融资、指数合作、期货产品、交易所买卖基金、金融机构国际化、绿色金融和专业资格便利化等多个范畴。 具体措施包括：融资方面，继续支持符合条件的境内企业赴港上市融资，支持符合条件的港股上市公司境内上市，支持符合条件的香港企业到内地发行债券，更好利用两个市场、两种资源融资发展；指数方面，支持指…"
