    "content": "新华社圣彼得堡8月3日电（记者陈畅）俄罗斯国防部3日发布消息说，俄北方舰队近日在巴伦支海举行的多兵种军事演习中发射多枚导弹，摧毁海上标靶。 消息说，“戈洛夫科海军上将”号护卫舰和“乌斯季诺夫元帅”号巡洋舰在演习中组成海上打击群，演习中还使用了“棱堡”导弹系统。此外，图-142反潜机、米格-29K舰载歼击机和伊尔-78加油机等参与演习。 演习期间，针对多个假想敌方目标，“戈洛夫科海军上将”号护卫舰发射“口径”巡航导弹，“乌斯季诺夫元帅”号巡洋舰发射“火山”巡航导弹，“奥廖尔”号核潜艇从水下发射“花岗岩”巡航导弹。所有…"
