    "content": "新华社莫斯科8月3日电（记者赵冰）俄罗斯方面3日表示，乌克兰军队对弗拉基米尔州、克拉斯诺达尔边疆区和别尔哥罗德州等地进行袭击，造成至少8人死亡、13人受伤。 俄罗斯弗拉基米尔州州长阿夫杰耶夫3日在社交媒体上说，乌克兰军队使用无人机袭击了该州的一处仓库，导致仓库起火，并造成3人受伤。俄侦查委员会发言人彼得连科同日表示，已就乌军相关袭击展开调查。 另据俄罗斯克拉斯诺达尔边疆区行动指挥部3日发布的消息，乌克兰一架无人机在当地一个村庄坠毁，造成4人死亡、10人受伤。同日，别尔哥罗德州代理州长舒瓦耶夫在社交媒体上说，过去24…"
