    "content": "新华社石家庄8月3日电 题：河北宁晋：产业大脑赋能传统产业数智化转型 新华社记者周舟、高博 记者近日走进我国北方线缆重镇河北省宁晋县，当地做了10多年生产制造的河北易缆网络科技有限公司董事长贾晓佳说，当年他提出要做“数据生意”时，产业链上下游的企业家们一头雾水；仅两三年间，这家企业开发的垂直行业大模型“易缆网”，从底层重塑了当地线缆传统产业。 宁晋线缆产业起步于20世纪80年代，经过40余年的发展，已形成完整全产业链体系，现有生产及配套企业2500多家，产品涵盖电力电缆、矿用电缆、橡套电缆等30多个系列、上千个品种…"
