    "content": "新华社广州8月3日电（记者杨深深、杨晓敏）“同心同行·强国有我”——2026年港澳青少年遇“舰”军营活动（湛江）3日在海军驻湛江某部正式开营。 8月3日，“同心同行·强国有我”——2026年港澳青少年遇“舰”军营活动（湛江）在海军驻湛江某部正式开营。这是港澳青少年参加开营仪式时唱国歌。新华社发（乔晨曦 摄） 开营仪式上，广东省港澳办主任陈丽文介绍，今年是中国共产党成立105周年、红军长征胜利90周年，组织港澳青少年走进海军军营，旨在引导他们在沉浸式体验中读懂祖国、读懂国防，深刻体悟与祖国血脉相连的家国情怀。 8月3…"
