    "description": "中新网合肥8月3日电 (江婉琪)“涂装工艺精度要求高，精度差一毫，品质就可能失之千里。”8月3日，在奇瑞汽车股份有限公司产业园四期涂装车间里，“00后”退役军人叶浩然正手持巡检本穿梭于设备间，他主要负责涂装输送设备及各类工艺设备的故障处置与日常检查维修。",
    "content": "中新网合肥8月3日电 (江婉琪)“涂装工艺精度要求高，精度差一毫，品质就可能失之千里。”8月3日，在奇瑞汽车股份有限公司产业园四期涂装车间里，“00后”退役军人叶浩然正手持巡检本穿梭于设备间，他主要负责涂装输送设备及各类工艺设备的故障处置与日常检查维修。"
