    "title": "三部门向陕西调拨6.5万件中央救灾物资",
    "link": "https://www.chinanews.com.cn/gn/2026/08-03/10671332.shtml",
    "pub_date": "2026-08-03 18:17:23",
    "author": "",
    "description": "中新网8月3日电 据应急管理部网站消息，8月3日，国家防灾减灾救灾委员会办公室、应急管理部针对陕西暴雨洪涝灾害及新一轮持续性强降雨天气影响，派出工作组实地查看灾情，协助和指导地方做好救灾工作。根据灾区救灾救助工作需要，会同国家粮食和物资储备局向陕西调拨帐篷、折叠床、毛毯、家庭应急包等6.5万件中央救灾物资，支持地方妥善做好受灾群众救灾救助和避险转移安置工作。",
    "content": "中新网8月3日电 据应急管理部网站消息，8月3日，国家防灾减灾救灾委员会办公室、应急管理部针对陕西暴雨洪涝灾害及新一轮持续性强降雨天气影响，派出工作组实地查看灾情，协助和指导地方做好救灾工作。根据灾区救灾救助工作需要，会同国家粮食和物资储备局向陕西调拨帐篷、折叠床、毛毯、家庭应急包等6.5万件中央救灾物资，支持地方妥善做好受灾群众救灾救助和避险转移安置工作。"
